"""Build the personal research site from reusable layouts and project records."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent.parent; OUT=ROOT/'dist'
projects=json.loads((ROOT/'content/projects.json').read_text())
def page(title,body,active='home',sidebar=False):
 nav=''.join(f'<a class="nav-link {"active" if active==key else ""}" href="{url}" {"aria-current=page" if active==key else ""}>{label}</a>' for key,url,label in [('home','/','Home'),('projects','/projects/','Projects'),('about','/about/','About')])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · Feng Gu</title><link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script></head><body><a href="#notebook" class="skip">Skip to content</a><header class="site-header"><a class="logo" href="/">Feng Gu · Research</a><nav aria-label="Main navigation">{nav}</nav></header><div class="page-layout {'' if sidebar else 'no-sidebar'}">{'<aside id="sidebar" class="sidebar" aria-label="Page sections"></aside>' if sidebar else ''}<main class="content-area"><div id="notebook" class="notebook">{body}</div><footer>Feng Gu · Personal research website · <a href="/">Home</a> · <a href="/projects/">Projects</a> · <a href="/about/">About</a></footer></main></div></body></html>'''
def save(path,text):
 f=OUT/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(text)
def rows():
 return ''.join(f'''<article class="project-row"><div><h3><a href="/projects/{p['slug']}/">{p['title']}</a></h3><p>{p['summary']}</p><a href="/projects/{p['slug']}/">{'Read the study' if p['status']=='Completed' else 'Open the working notebook'} →</a></div><span class="badge {'ongoing' if p['status']=='Ongoing' else ''}">{p['status']}</span></article>''' for p in projects)
save(Path('index.html'),page('Home','''<p class="eyebrow">Personal research website</p><h1>Feng Gu</h1><p class="intro">Statistical research, ecological questions, and mathematical exploration.</p><p>This website brings my projects together in one place. Each project has its own research page, with the question, analytical framework, results, and supporting materials organized into sections.</p><div class="notice">Template demonstration: the two example projects below contain illustrative content.</div><h2>Selected projects</h2>'''+rows()+'''<p><a href="/projects/">View all projects and the reusable project structure →</a></p><h2>About this collection</h2><p>Completed studies present their full research story. Ongoing projects show the current evidence, open questions, and next steps.</p><p><a href="/about/">About me →</a></p>'''))
save(Path('projects/index.html'),page('Projects','''<h1>Projects</h1><p class="intro">A collection of completed studies and work in progress.</p><p>Choose a project to explore its sections using the left sidebar.</p>'''+rows()+'''<h2>A reusable structure</h2><p>The original thesis structure becomes a general research hierarchy:</p><table><thead><tr><th>Thesis structure</th><th>General project structure</th></tr></thead><tbody><tr><td>Chapter</td><td>Project objective: what question are we addressing?</td></tr><tr><td>Framework</td><td>Analytical framework: what logic answers the question?</td></tr><tr><td>Computation process</td><td>Implementation: what inputs, methods, and outputs carry it out?</td></tr></tbody></table><p>Results, discussion, resources, and progress records sit alongside this hierarchy. Include only sections that serve the project.</p><p><a href="/projects/project-template/">Open the blank project template →</a></p>''','projects'))
save(Path('about/index.html'),page('About','''<h1>About</h1><p class="intro">Feng Gu</p><p>This page is reserved for your biography, research interests, education, and contact information.</p><h2>Research interests</h2><p class="template-label">Add a short explanation of the questions and methods that connect your work.</p><h2>Background</h2><p class="template-label">Add your academic background and relevant experience.</p><h2>Contact & links</h2><p class="template-label">Add your preferred email, GitHub, publications, or other professional links.</p>''','about'))
for p in projects:
 b=f'''<p class="back"><a href="/projects/">← All projects</a></p><h1>{p['title']}</h1><p class="intro">{p['summary']}</p><span class="badge {'ongoing' if p['status']=='Ongoing' else ''}">{p['status']}</span><div class="notice">Illustrative project · This content demonstrates the website structure and is not a claim about actual research.</div>{p['content']}<div class="related"><a href="/projects/">← Return to all projects</a></div>'''
 save(Path('projects')/p['slug']/'index.html',page(p['title'],b,'projects',True))
sections=[('Overview','State the question, motivation, current status, and main takeaway.'),('Project objective','Explain the larger research objective and the scope of this project.'),('Analytical frameworks','Describe the logic used to address the objective.'),('Framework 1','State one analytical question, its assumptions, and the evidence needed.'),('Implementation processes','For each process, document inputs, method or tools, outputs, and checks.'),('Data & preparation','Describe sources, variables, cleaning, transformations, and exclusions.'),('Results','Present the main findings with figures, tables, and captions. Mark preliminary findings clearly.'),('Discussion & limitations','Explain the interpretation, uncertainty, and limits of the findings.'),('Conclusion / next steps','Summarize a completed study, or list the next questions for ongoing work.'),('Resources & drafts','Link to available code, data, papers, slides, and drafts.'),('Progress records','Record meaningful updates, decisions, and milestones.')]
b='<p><a href="/projects/">← All projects</a></p><h1>Project title</h1><p class="intro">One sentence describing the question and contribution.</p><div class="notice">Reusable blank example · Replace prompts with your content and remove unused sections.</div>'
for name,prompt in sections:
 level='h3' if name=='Framework 1' else 'h2'
 b+=f'<{level}>{name}</{level}><p class="template-label">{prompt}</p>'
save(Path('projects/project-template/index.html'),page('Project template',b,'projects',True))
